/**
 * 静默时间（免打扰）。
 *
 * 参考 `F:\work\shiny colors\src\quiet-hours.mjs`，但按本项目需要裁剪：
 *   - 只挡主动插话；被 @ 和私聊照常回复，因此不需要管理员例外，也不做入站闸门；
 *   - 只有全局一套配置，不做每群覆盖；
 *   - 节假日启动时拉一次（6 小时为下限），失败按"周末规则"兜底；
 *   - 内置 Node 没有编译 Intl，时区靠固定 UTC+8 偏移手算。
 *
 * 判定是纯函数（utc8Parts / windowContains / dayKindOf / isQuietAt），
 * 类只负责读配置、读覆盖、拉节假日、写状态快照。
 */
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

export const QUIET_SCHEMA_VERSION = 1;
export const TZ_OFFSET_MINUTES = 8 * 60;
export const HOLIDAY_MIN_INTERVAL_MS = 6 * 60 * 60 * 1000;
const WRITE_THROTTLE_MS = 3000;
const HOLIDAY_TIMEOUT_MS = 8000;
const holidayUrl = year => `https://timor.tech/api/holiday/year/${year}`;

/** 配置缺失或损坏时的默认值：默认开启，工作日 23:00–08:00，休息日 23:00–09:00。 */
export const DEFAULT_SETTINGS = {
    enabled: true,
    holidays: 'cn',
    workdays: [1, 2, 3, 4, 5],
    workdayWindows: [[1380, 480]],
    offdayWindows: [[1380, 540]],
};

const pad = value => String(value).padStart(2, '0');

/** 取"北京时间"的日期分量。返回的 minutes 是当天 0 点起的分钟数。 */
export function utc8Parts(now = new Date(), offsetMinutes = TZ_OFFSET_MINUTES) {
    const shifted = new Date(now.getTime() + offsetMinutes * 60_000);
    const year = shifted.getUTCFullYear();
    const month = shifted.getUTCMonth() + 1;
    const day = shifted.getUTCDate();
    const hours = shifted.getUTCHours();
    const minutes = shifted.getUTCMinutes();
    return {
        year,
        month,
        day,
        date: `${year}-${pad(month)}-${pad(day)}`,
        // ISO 星期：周一 1 … 周日 7。
        isoDow: shifted.getUTCDay() === 0 ? 7 : shifted.getUTCDay(),
        minutes: hours * 60 + minutes,
        localTime: `${pad(hours)}:${pad(minutes)}`,
    };
}

/** '23:00' → 1380；非法返回 undefined。 */
export function parseClock(value) {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(value ?? '').trim());
    if (!match) return undefined;
    const hours = Number(match[1]);
    const minutes = Number(match[2]);
    if (!Number.isFinite(hours) || !Number.isFinite(minutes) || hours > 23 || minutes > 59) return undefined;
    return hours * 60 + minutes;
}

/** 1380 → '23:00'。 */
export function formatClock(totalMinutes) {
    const value = ((Math.round(totalMinutes) % 1440) + 1440) % 1440;
    return `${pad(Math.floor(value / 60))}:${pad(value % 60)}`;
}

/**
 * 规范化时间段数组。接受 `[['23:00','08:00']]` 或 `[[1380,480]]` 两种写法，
 * 起止相同、越界、格式错误的项直接丢弃。返回 undefined 表示"这一项不是数组"。
 */
export function normalizeWindows(raw) {
    if (!Array.isArray(raw)) return undefined;
    const windows = [];
    for (const item of raw) {
        if (!Array.isArray(item) || item.length !== 2) continue;
        const start = typeof item[0] === 'number' ? item[0] : parseClock(item[0]);
        const end = typeof item[1] === 'number' ? item[1] : parseClock(item[1]);
        if (!Number.isFinite(start) || !Number.isFinite(end)) continue;
        if (start < 0 || end < 0 || start >= 1440 || end >= 1440 || start === end) continue;
        windows.push([start, end]);
    }
    return windows;
}

/** 把磁盘上的配置对象补全成可判定的设置。 */
export function normalizeSettings(raw) {
    const value = raw && typeof raw === 'object' ? raw : {};
    const workday = value.workday && typeof value.workday === 'object' ? value.workday : {};
    const offday = value.offday && typeof value.offday === 'object' ? value.offday : {};
    const workdays = Array.isArray(workday.weekdays)
        ? workday.weekdays.map(Number).filter(day => Number.isInteger(day) && day >= 1 && day <= 7)
        : DEFAULT_SETTINGS.workdays;
    return {
        enabled: value.enabled !== false,
        holidays: value.holidays === 'none' ? 'none' : DEFAULT_SETTINGS.holidays,
        workdays: workdays.length > 0 ? [...new Set(workdays)].sort((a, b) => a - b) : DEFAULT_SETTINGS.workdays,
        workdayWindows: normalizeWindows(workday.windows) ?? DEFAULT_SETTINGS.workdayWindows,
        offdayWindows: normalizeWindows(offday.windows) ?? DEFAULT_SETTINGS.offdayWindows,
    };
}

/** 当前时刻是否落在某个窗口内；支持跨夜（start > end）。 */
export function windowContains(window, minutes) {
    const [start, end] = window;
    if (!Number.isFinite(start) || !Number.isFinite(end) || start === end) return false;
    return start < end ? minutes >= start && minutes < end : minutes >= start || minutes < end;
}

/** 当前窗口 / 明天窗口结束时刻（毫秒时间戳），用于"到 08:00 恢复"。 */
export function windowEndMs(nowMs = Date.now(), window, offsetMinutes = TZ_OFFSET_MINUTES) {
    const [start, end] = window;
    const shifted = new Date(nowMs + offsetMinutes * 60_000);
    const dayStartUtc = Date.UTC(shifted.getUTCFullYear(), shifted.getUTCMonth(), shifted.getUTCDate()) - offsetMinutes * 60_000;
    const parts = utc8Parts(new Date(nowMs), offsetMinutes);
    const endToday = dayStartUtc + end * 60_000;
    if (start < end) return endToday;
    // 跨夜窗口：凌晨时段（minutes < end）结束在今天，深夜时段结束在明天。
    return parts.minutes < end ? endToday : endToday + 24 * 60 * 60 * 1000;
}

/**
 * 今天算工作日还是休息日：
 *   法定节假日数据里有今天 → 以它为准（`holiday: true` 放假、`false` 调休上班）；
 *   没有 → 按 workdays 里的星期判断。
 */
export function dayKindOf(parts, settings, days) {
    const today = days && typeof days === 'object' ? days[parts.date] : undefined;
    if (today && typeof today.holiday === 'boolean') return today.holiday ? 'offday' : 'workday';
    return settings.workdays.includes(parts.isoDow) ? 'workday' : 'offday';
}

/** 生效中的临时覆盖；过期返回 null。 */
export function activeOverride(override, nowMs = Date.now()) {
    if (!override || !Number.isFinite(override.until)) return null;
    return override.until > nowMs ? override : null;
}

/**
 * 纯判定：返回 `{ state, dayKind, window, until, holiday }`。
 * `state` 为 'normal' | 'quiet' | 'override'。
 */
export function isQuietAt({ nowMs = Date.now(), settings, override, days, offsetMinutes = TZ_OFFSET_MINUTES } = {}) {
    const effective = settings ?? DEFAULT_SETTINGS;
    const parts = utc8Parts(new Date(nowMs), offsetMinutes);
    const dayKind = dayKindOf(parts, effective, days);
    const today = days && typeof days === 'object' ? days[parts.date] : undefined;
    const windows = dayKind === 'offday' ? effective.offdayWindows : effective.workdayWindows;
    const hit = windows.find(window => windowContains(window, parts.minutes));
    const until = hit ? windowEndMs(nowMs, hit, offsetMinutes) : undefined;
    const base = {
        dayKind,
        window: hit ? `${formatClock(hit[0])}-${formatClock(hit[1])}` : '',
        until,
        holiday: today && today.holiday ? today.name : '',
    };
    if (!effective.enabled) return { ...base, state: 'normal' };
    const forced = activeOverride(override, nowMs);
    if (forced) return { ...base, state: 'override', until: forced.until };
    return { ...base, state: hit ? 'quiet' : 'normal' };
}

/** 静默时间读写 + 状态快照。 */
export class QuietHours {
    constructor({ dir, logger, offsetMinutes = TZ_OFFSET_MINUTES, fetchImpl = globalThis.fetch } = {}) {
        this.dir = dir;
        this.logger = logger;
        this.offsetMinutes = offsetMinutes;
        this.fetchImpl = fetchImpl;
        this.settings = undefined;
        this.settingsAt = 0;
        this.override = null;
        this.overrideAt = 0;
        this.holidays = { year: 0, days: {}, fetchedAt: 0 };
        this.suppressed = 0;
        this.writeAt = 0;
        this.pendingWrite = undefined;
    }

    get configPath() { return this.dir ? join(this.dir, 'quiet-hours.json') : undefined; }
    get overridePath() { return this.dir ? join(this.dir, 'quiet-hours-override.json') : undefined; }
    get holidayPath() { return this.dir ? join(this.dir, 'holidays-cn.json') : undefined; }
    get statusPath() { return this.dir ? join(this.dir, 'quiet-hours-state.json') : undefined; }

    /** 配置 2 秒内复用，避免每条群消息都读盘。 */
    async loadSettings() {
        const now = Date.now();
        if (this.settings && now - this.settingsAt < 2000) return this.settings;
        const path = this.configPath;
        let raw;
        if (path) {
            try { raw = JSON.parse(await readFile(path, 'utf8')); } catch (err) { if (err?.code !== 'ENOENT') this.logger?.warn?.(`静默时间配置读取失败: ${err.message}`); }
        }
        this.settings = normalizeSettings(raw);
        this.settingsAt = now;
        return this.settings;
    }

    /** 覆盖文件 1 秒内复用：界面上点完要在下一条消息就生效。 */
    async loadOverride() {
        const now = Date.now();
        if (now - this.overrideAt < 1000) return this.override;
        const path = this.overridePath;
        let raw;
        if (path) {
            try { raw = JSON.parse(await readFile(path, 'utf8')); } catch (err) { if (err?.code !== 'ENOENT') this.logger?.warn?.(`静默覆盖读取失败: ${err.message}`); }
        }
        const until = Number(raw?.until);
        this.override = Number.isFinite(until) && until > 0 ? { kind: String(raw?.kind ?? ''), until } : null;
        this.overrideAt = now;
        return this.override;
    }

    /**
     * 节假日表。优先用 6 小时内的内存/磁盘缓存，过期才联网拉；
     * 拉取失败保留旧数据（哪怕过期），仍失败就交给 dayKindOf 按星期兜底。
     */
    async ensureHolidays(force = false) {
        const now = Date.now();
        const year = utc8Parts(new Date(now), this.offsetMinutes).year;
        const fresh = this.holidays.year === year && now - this.holidays.fetchedAt < HOLIDAY_MIN_INTERVAL_MS;
        if (fresh && !force) return this.holidays.days;
        if (!fresh) await this.readHolidayCache(year);
        const cachedFresh = this.holidays.year === year && now - this.holidays.fetchedAt < HOLIDAY_MIN_INTERVAL_MS;
        if (cachedFresh && !force) return this.holidays.days;
        try {
            await this.fetchHolidays(year);
        } catch (err) {
            this.logger?.warn?.(`节假日拉取失败，按星期规则判断: ${err?.message ?? err}`);
        }
        return this.holidays.days;
    }

    /** 启动时调用一次（用户要求"启动拉一次就好"）。 */
    async refreshOnStart() {
        try { await this.ensureHolidays(true); } catch { /* ensureHolidays 内部已兜底 */ }
        await this.loadSettings();
        await this.loadOverride();
        await this.snapshot();
    }

    async readHolidayCache(year) {
        const path = this.holidayPath;
        if (!path || this.holidays.year === year) return;
        try {
            const value = JSON.parse(await readFile(path, 'utf8'));
            if (value?.year === year && value?.days && typeof value.days === 'object') {
                this.holidays = { year, days: value.days, fetchedAt: Number(value.fetchedAt) || 0 };
            }
        } catch (err) { if (err?.code !== 'ENOENT') this.logger?.warn?.(`节假日缓存读取失败: ${err.message}`); }
    }

    async fetchHolidays(year) {
        if (typeof this.fetchImpl !== 'function') throw new Error('当前运行时没有 fetch');
        const signal = typeof globalThis.AbortSignal?.timeout === 'function' ? globalThis.AbortSignal.timeout(HOLIDAY_TIMEOUT_MS) : undefined;
        const response = await this.fetchImpl(holidayUrl(year), { signal, headers: { accept: 'application/json' } });
        if (!response?.ok) throw new Error(`HTTP ${response?.status ?? '?'}`);
        const payload = await response.json();
        const source = payload?.holiday;
        if (!source || typeof source !== 'object') throw new Error('返回结构里没有 holiday');
        const days = {};
        for (const [key, value] of Object.entries(source)) {
            if (!/^\d{2}-\d{2}$/.test(key)) continue;
            if (typeof value?.holiday !== 'boolean') continue;
            days[`${year}-${key}`] = { holiday: value.holiday, name: typeof value.name === 'string' ? value.name : '' };
        }
        this.holidays = { year, days, fetchedAt: Date.now() };
        this.logger?.info?.(`节假日表已更新 ${year} 年：${Object.keys(days).length} 条`);
        const path = this.holidayPath;
        if (path) {
            try {
                await mkdir(this.dir, { recursive: true });
                const temp = `${path}.tmp`;
                await writeFile(temp, JSON.stringify({ year, days, fetchedAt: this.holidays.fetchedAt }), 'utf8');
                await rename(temp, path);
            } catch (err) { this.logger?.warn?.(`节假日缓存写入失败: ${err.message}`); }
        }
        return days;
    }

    /** 计算当前状态（不写盘）。 */
    async evaluate(nowMs = Date.now()) {
        const settings = await this.loadSettings();
        const override = await this.loadOverride();
        const days = await this.ensureHolidays();
        const parts = utc8Parts(new Date(nowMs), this.offsetMinutes);
        const result = isQuietAt({ nowMs, settings, override, days, offsetMinutes: this.offsetMinutes });
        return { ...result, settings, override: activeOverride(override, nowMs), parts };
    }

    /** 主动插话判定入口。 */
    async isQuiet(nowMs = Date.now()) {
        try {
            const state = await this.evaluate(nowMs);
            return state.state === 'quiet';
        } catch (err) {
            this.logger?.warn?.(`静默时间判定失败，按不静默处理: ${err?.message ?? err}`);
            return false;
        }
    }

    /** 被静默挡下一次主动插话时调用，计数进状态文件。 */
    async recordSuppressed() {
        this.suppressed += 1;
        return this.snapshot();
    }

    /** 生成并落地状态快照（5 秒节流），供 App 的设置页/总览展示。 */
    async snapshot(nowMs = Date.now()) {
        const state = await this.evaluate(nowMs);
        const payload = {
            schemaVersion: QUIET_SCHEMA_VERSION,
            enabled: state.settings.enabled,
            state: state.state,
            dayKind: state.dayKind,
            window: state.window,
            until: state.until ?? 0,
            holiday: state.holiday,
            override: state.override ?? null,
            localTime: state.parts.localTime,
            date: state.parts.date,
            suppressed: this.suppressed,
        };
        const now = Date.now();
        if (now - this.writeAt >= WRITE_THROTTLE_MS) {
            this.writeAt = now;
            await this.writeStatus(payload);
        }
        return payload;
    }

    async writeStatus(payload) {
        const path = this.statusPath;
        if (!path) return;
        try {
            await mkdir(this.dir, { recursive: true });
            const temp = `${path}.tmp`;
            await writeFile(temp, JSON.stringify({ ...payload, updatedAt: Date.now() }), 'utf8');
            await rename(temp, path);
        } catch (err) { this.logger?.warn?.(`静默状态写入失败: ${err.message}`); }
    }
}
